examples.template:
MonarchWorkspaceSwitcher(
    selection: $workspace,
    workspaces: [
        MonarchWorkspaceOption(id: {{workspaces.0.id}}, name: {{workspaces.0.name}}, handle: {{workspaces.0.handle}}),
        MonarchWorkspaceOption(id: {{workspaces.1.id}}, name: {{workspaces.1.name}}, handle: {{workspaces.1.handle}}),
        MonarchWorkspaceOption(id: {{workspaces.2.id}}, name: {{workspaces.2.name}}, handle: {{workspaces.2.handle}}, keywords: {{workspaces.2.keywords}}),
    ],
    manageURL: URL(string: {{manageHref}}),
    onCreate: {
        // The app opens its Create workspace screen.
    }
)
.frame(width: 240)

examples.code:
MonarchWorkspaceSwitcher(
    selection: $workspace,
    workspaces: [
        MonarchWorkspaceOption(id: "w1", name: "Acme", handle: "acme"),
        MonarchWorkspaceOption(id: "w2", name: "Northfield Traders", handle: "northwind"),
        MonarchWorkspaceOption(id: "w3", name: "Globex", handle: "globex", keywords: "globex corporation"),
    ],
    manageURL: URL(string: "https://id.example.com/workspaces"),
    onCreate: {
        // The app opens its Create workspace screen.
    }
)
.frame(width: 240)

examples.setup:
@State private var workspace: String? = "w1"
private let workspaces = (1...8).map {
    MonarchWorkspaceOption(id: "w\($0)", name: "Client \($0)", handle: "client\($0)")
}
